def evaluate_login_risk(ctx: dict) -> str:
    score = 0
    if ctx["asn_type"] in ("tor_exit", "hosting_vps"):
        score += 55
    if ctx["travel_kmh"] > 800 and not ctx["known_corporate_vpn"]:
        score += 45
    if not ctx["trusted_device_binding"]:
        score += 25
    if score >= 70:
        return "STEP_UP_WEBAUTHN_ONLY"  # Block TOTP/SMS; require FIDO2
    if score >= 30:
        return "STEP_UP_NUMBER_MATCH"   # 2-digit push or WebAuthn
    return "ALLOW_SESSION"
